import math

def hit_rate_t(hits, n, p0):
    # (hits / n - p0) / sqrt(p0 (1 - p0) / n)
    return (hits / n - p0) / math.sqrt(p0 * (1 - p0) / n)

def pnl_after_costs(signal, returns, cost_bp):
    # signal: +1 or -1 each day; pay cost_bp / 10000 times |change in position|; start flat
    # return the cumulative P&L after each day
    out, total, prev = [], 0.0, 0
    for s, r in zip(signal, returns):
        total += s * r - cost_bp / 10000 * abs(s - prev)
        prev = s
        out.append(total)
    return out
